contract InvMutTest {
    C c;

    constructor() payable { c = new C{value: 1 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 unused) public payable {
        // Ensure this test contract has not previously committed; use a parameterized
        // gas limit so the property ranges over at least one input.
        require(unused >= 0);

        uint256 beforeBalance = address(c).balance;

        bool reverted;
        c.settle(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && address(c).balance == beforeBalance);
    }

    receive() external payable {}
}

